<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; requireRole('patient');
$query = $pdo->prepare('SELECT m.record_type, m.record_title, m.record_description, m.created_at, d.doctor_name FROM medical_records m JOIN patients p ON p.id = m.patient_id JOIN doctors d ON d.id = m.doctor_id WHERE p.user_id = :user_id ORDER BY m.created_at DESC'); $query->execute([':user_id' => $_SESSION['user_id']]); $records = $query->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'Medical Records'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">Patient space</p><h1 class="h2">Medical Records</h1></div></div><?php foreach ($records as $record): ?><article class="card border-0 shadow-sm mb-3"><div class="card-body"><h2 class="h5 mb-1"><?= e($record['record_title']) ?></h2><div class="small text-muted"><?= e($record['record_type']) ?> | <?= e($record['doctor_name']) ?> | <?= e($record['created_at']) ?></div><p class="mt-3 mb-0"><?= e($record['record_description']) ?></p></div></article><?php endforeach; ?><?php if (!$records): ?><div class="alert alert-light border">No medical records found.</div><?php endif; ?><?php require __DIR__ . '/../includes/footer.php'; ?>